        return None

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url:
        raise ValueError("Repository URL must be provided.")

    headers = {'Accept': 'application/vnd.github.v3+json'}
    try:
        response = requests.get(repo_url, headers=headers)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        if response.status_code == 403:
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.") from e
        else:
            raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}") from e
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}") from e

    repo_info = response.json()
    open_issues = repo_info.get('open_issues_count', 0)
    if open_issues > 1000:
        logging.warning(f"Repository has a large number of open issues: {open_issues}")

    return repo_info

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        if detected['confidence'] < 0.5:
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']
    decoded = content.decode(from_encoding)
    re_encoded = decoded.encode(to_encoding)
    return json.loads(re_encoded)

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        url_legacy_compatible = '.internal.' in url or url.startswith('http://localhost')
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(url, verify=verify_cert)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
        dicts = []
        for script in scripts:
            text = script.string
            if text:
                try:
                    evaluated = ast.literal_eval(text.strip())
                    if isinstance(evaluated, dict):
                        dicts.append(evaluated)
                except (ValueError, SyntaxError):
                    continue
        return dicts
    except:
        return []

